const getEmployeeLeaveBalances = async (company) => {
    company_id.value = company
    loading.value = true
    try{
         const response = await axiosInstance.get(`leave-balances?company_id=${company}`);
            employeeLeaveBalances.value = response.data.map((item, index) => ({
                ...item,
                SNo: index + 1,
                id: item.id,
                name: item.employee.name,
                department: item.employee.department,
                contract_date:item.employee.contract_date,
                leave_days:item.total_leave_days,
                leave_balance: 28 - Number(item.total_leave_days)
            }));

    }catch(error){
        showError(error.message);
        console.log(error);
    }finally{
        loading.value = false
    }
 
}

const printEmployeesLeaveBalance = async () => {
